WITH cleaned AS (SELECT *, CASE WHEN event_type IN ('click', 'page_view') THEN 'Group A' ELSE 'Other' END AS event_type_group, CASE WHEN duration_sec >= 406 THEN 'High' WHEN duration_sec >= 206 THEN 'Medium' ELSE 'Low' END AS duration_sec_band FROM web_events WHERE event_time > DATE '2023-08-21' AND page IS NOT NULL), gaps AS (SELECT *, CASE WHEN LAG(event_time) OVER (PARTITION BY page ORDER BY event_time, id) IS NULL OR event_time > LAG(event_time) OVER (PARTITION BY page ORDER BY event_time, id) + INTERVAL '60' DAY THEN 1 ELSE 0 END AS is_new_session FROM cleaned), sessions_web_events AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY page ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM gaps) SELECT CASE WHEN is_new_session >= 1 THEN 'LARGE' ELSE 'SMALL' END AS is_new_session_tier, STDDEV_SAMP(duration_sec) AS duration_sec_stddev, AVG(is_new_session) FILTER (WHERE event_type = 'search') AS search_avg_is_new_session, SIZE(COLLECT_SET(page)) AS num_pages, AVG(island_id) FILTER (WHERE event_type = 'page_view') AS page_view_avg_island_id, SIZE(COLLECT_SET(event_type)) AS num_event_types, MAX(duration_sec) AS max_duration_sec FROM sessions_web_events GROUP BY is_new_session_tier HAVING SIZE(COLLECT_SET(event_type)) > 1;
